def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    centers=[]
    for r in range(1,h-1):
        for c in range(1,w-1):
            if grid[r][c] == 2 and all(grid[rr][cc] == 3 for rr,cc in [(r-1,c-1),(r-1,c),(r-1,c+1),(r,c-1),(r,c+1),(r+1,c-1),(r+1,c),(r+1,c+1)]):
                centers.append((r,c))
    anchors=set()
    for r,c in centers:
        row_score=sum(v==2 for v in grid[r])
        col_score=sum(grid[rr][c]==2 for rr in range(h))
        if row_score >= col_score:
            # Horizontal separator: emit along its perpendicular column.
            line=[(rr,c) for rr in range(h)]
        else:
            # Vertical separator: emit along its perpendicular row.
            line=[(r,cc) for cc in range(w)]
        for rr,cc in line:
            if grid[rr][cc]==2:
                anchors.add((rr,cc))
            elif grid[rr][cc]==0:
                out[rr][cc]=1
    for ar,ac in anchors:
        for rr in range(max(0,ar-1),min(h,ar+2)):
            for cc in range(max(0,ac-1),min(w,ac+2)):
                if (rr,cc) in anchors or grid[rr][cc]==3:
                    continue
                out[rr][cc]=1
    return out
